export const QUARTIERS: QuartierData[] = RAW.map(r => ({
  key: r[0], gouv: r[1], delegation: r[2], codeDel: r[3],
  quartier: r[4], typeZone: r[5], coeffQ: r[6],
  ancien: r[7], neuf: r[8], transaction: r[9],
  loyerNm: r[10], loyerM: r[11], decote: r[12],
}));

// ─── INDEX DE RECHERCHE PAR DÉLÉGATION ───
const _delIndex: Record<string, QuartierData[]> = {};
for (const q of QUARTIERS) {
  if (!_delIndex[q.codeDel]) _delIndex[q.codeDel] = [];
  _delIndex[q.codeDel].push(q);
}

/** Retourne tous les quartiers d'une délégation */
export function getQuartiersByDelegation(codeDel: string): QuartierData[] {
  return _delIndex[codeDel] ?? [];
}

/** Retourne le quartier le plus proche par coefficient */
export function findQuartier(gouvernorat: string, delegation: string, quartier?: string): QuartierData | undefined {
  const del = delegation.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const qLower = quartier?.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  
  // Find matching delegation code
  let matchingDel: string | undefined;
  for (const [code, items] of Object.entries(_delIndex)) {
    if (items[0]?.gouv === gouvernorat) {
      const dNorm = items[0].delegation.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      if (dNorm.includes(del) || del.includes(dNorm)) {
        matchingDel = code;
        break;
      }
    }
  }
  
  if (!matchingDel) return undefined;
  
  const quartiers = _delIndex[matchingDel];
  if (!quartier || !qLower) {
    // Return median quartier (by coefficient)
    const sorted = [...quartiers].sort((a, b) => a.coeffQ - b.coeffQ);
    return sorted[Math.floor(sorted.length / 2)];
  }
  
  // Find exact or partial match
  for (const q of quartiers) {
    const qNorm = q.quartier.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    if (qNorm.includes(qLower) || qLower.includes(qNorm)) return q;
  }
  
  // Return closest by coefficient
  return quartiers.reduce((best, q) => {
    return Math.abs(q.coeffQ - 1.0) < Math.abs(best.coeffQ - 1.0) ? q : best;
  }, quartiers[0]);
}

/** Transaction moyenne d'une délégation */
export function getDelAvgTransaction(codeDel: string): number {
  const list = _delIndex[codeDel] ?? [];
  if (list.length === 0) return 0;
  return list.reduce((s, q) => s + q.transaction, 0) / list.length;
}

/** Loyer moyen non meublé d'une délégation */
export function getDelAvgRentNm(codeDel: string): number {
  const list = _delIndex[codeDel] ?? [];
  if (list.length === 0) return 0;
  return list.reduce((s, q) => s + q.loyerNm, 0) / list.length;
}

